import {getParentProjectIds} from './ProjectBuildTypeSelect.selectors'
import type {CheckedItem, CheckedItems, CheckState, Direction} from './ProjectBuildTypeSelect.types'

import styles from './ProjectBuildTypeSelect.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

const SEARCH_HEIGHT = 40
const PADDING_BOTTOM = 8
const HINT_HEIGHT = 32
const PLACEHOLDER_HEIGHT = 32

type ProjectBuildTypeSelectFormProps = {
  allItemName?: string
  allItemSelectable?: boolean
  buildTypesSelectable?: boolean
  projectsSelectable?: boolean
  nothingSelectable?: boolean
  expandAll?: boolean
  excludedBuildTypes?: ReadonlyArray<BuildTypeId> | null | undefined
  includedBuildTypes?: ReadonlyArray<BuildTypeId> | null | undefined
  includedProjects?: ReadonlyArray<ProjectId> | null | undefined
  includedRootProjects?: ReadonlyArray<ProjectId> | null | undefined
  disabledProjects?: ReadonlyArray<ProjectId> | null | undefined
  includeRoot?: boolean
  containerClassName?: string
  hint?: string | null | undefined
  hintAction?: string | null | undefined
  onHintAction?: () => unknown
  selected?: ProjectOrBuildTypeNode | null
  checked?: ReadonlyArray<ProjectOrBuildTypeNode>
  onSelect?: (arg0: ProjectOrBuildTypeNode | null | undefined) => unknown
  onCheck?: (arg0: ReadonlyArray<ProjectOrBuildTypeNode>) => unknown
  multiselect?: boolean
  forceFetch?: boolean
  propagateCheck?: boolean
  withPipelines?: boolean
  hidePopup(): void
}

const getChildren = (
  items: KeyValue<SidebarItemId, ProjectsTreeItem>,
  parentItem: ProjectsTreeItem,
) =>
  [
    ...(parentItem.childrenBuildTypesIds?.map(
      id => items[generateSidebarItemId(currentServerId, 'buildType', id)],
    ) ?? []),
    ...(parentItem.childrenProjectsIds?.map(
      id => items[generateSidebarItemId(currentServerId, 'project', id)],
    ) ?? []),
  ].filter(notNull)

const matchNode = (checkedItems: CheckedItems, node: ProjectOrBuildTypeNode | null | undefined) =>
  node?.id != null ? checkedItems[node.nodeType]?.[node.id] : null

function getSidebarKey(node: ProjectOrBuildTypeNode) {
  switch (node.nodeType) {
    case 'project':
      return generateSidebarItemId(currentServerId, 'project', node.id)

    case 'bt':
      return generateSidebarItemId(currentServerId, 'buildType', node.id)

    default:
      return null
  }
}

function getItem(items: KeyValue<SidebarItemId, ProjectsTreeItem>, node: ProjectOrBuildTypeNode) {
  const key = getSidebarKey(node)
  return key != null ? items[key] : null
}

function checkItem(
  items: KeyValue<SidebarItemId, ProjectsTreeItem>,
  checkedItems: CheckedItems,
  item: ProjectsTreeItem,
  state: CheckState = 'CHECKED',
  direction?: Direction,
): boolean {
  const node = getNodeFromItem(item)

  if (node?.id == null) {
    return false
  }

  const match = matchNode(checkedItems, node)

  if (direction != null && direction !== 'NOPROPAGATE' && match?.state === state) {
    return false
  }

  let hasChanged = false
  if (match?.state !== state) {
    hasChanged = true
    checkedItems[node.nodeType] ??= {}
    checkedItems[node.nodeType]![node.id] = {
      node,
      state,
    }
  }

  if (direction === 'NOPROPAGATE') {
    return hasChanged
  }

  if (direction !== 'UP' && item.hasChildren === true) {
    const children = getChildren(items, item)

    for (const child of children) {
      const childHasChanged = checkItem(items, checkedItems, child, 'CHECKED', 'DOWN')
      hasChanged ||= childHasChanged
    }
  }

  const parent =
    direction === 'DOWN' || item.parentId == null
      ? null
      : getItem(items, getProjectFilter(item.parentId))

  if (parent != null && matchNode(checkedItems, getNodeFromItem(parent))?.state !== 'CHECKED') {
    const siblings = getChildren(items, parent)
    let parentState = state

    if (
      parentState === 'CHECKED' &&
      !siblings.every(
        sibling => matchNode(checkedItems, getNodeFromItem(sibling))?.state === 'CHECKED',
      )
    ) {
      parentState = 'INDETERMINATE'
    }

    const parentHasChanged = checkItem(items, checkedItems, parent, parentState, 'UP')
    hasChanged ||= parentHasChanged
  }
  return hasChanged
}

function uncheckItem(
  items: KeyValue<SidebarItemId, ProjectsTreeItem>,
  checkedItems: CheckedItems,
  item: ProjectsTreeItem,
  direction?: Direction,
): boolean {
  const node = getNodeFromItem(item)

  if (node?.id == null) {
    return false
  }

  const matchedItem = matchNode(checkedItems, node)

  if (matchedItem == null) {
    return false
  }

  delete checkedItems[node.nodeType]![node.id]

  if (direction === 'NOPROPAGATE') {
    return true
  }

  const parent =
    direction === 'DOWN' || item.parentId == null
      ? null
      : getItem(items, getProjectFilter(item.parentId))
  if (parent != null) {
    uncheckItem(items, checkedItems, parent, 'UP')
  }

  if (direction !== 'UP' && item.hasChildren === true) {
    const children = getChildren(items, item)

    for (const child of children) {
      uncheckItem(items, checkedItems, child, 'DOWN')
    }
  }

  return true
}

const normalizeChecks = (
  items: KeyValue<SidebarItemId, ProjectsTreeItem>,
  checkedItems: readonly ProjectOrBuildTypeNode[],
  propagateCheck: boolean,
): CheckedItems => {
  const result: CheckedItems = {}
  checkedItems.forEach(node => {
    const item = getItem(items, node)
    if (item != null) {
      checkItem(items, result, item, 'CHECKED', propagateCheck ? undefined : 'NOPROPAGATE')
    }
  })
  return result
}

const getExpandAll = (
  defaultTree: WritableMap<FederationServerId, ProjectsTreeType | null | undefined>,
) =>
  Object.fromEntries(
    defaultTree
      .get(currentServerId)
      ?.data.map(item =>
        item.itemType === 'project'
          ? [
              item.id,
              {
                id: item.id,
                expandState: 'EXPANDED',
              },
            ]
          : null,
      )
      .filter(notNull) ?? [],
  )

const emptyTree: ProjectsTreeType = {
  data: [],
  hash: emptyMap,
}

const flattenCheckedItems = (checkedItems: CheckedItems): CheckedItem[] =>
  objectValues(checkedItems).flatMap(value => objectValues(value))

const getSelectedItems = (
  projectsSelectable: boolean,
  items: KeyValue<SidebarItemId, ProjectsTreeItem>,
  checkedItems: CheckedItems,
  propagateCheck?: boolean,
): ProjectOrBuildTypeNode[] =>
  flattenCheckedItems(checkedItems)
    .filter(({node, state}: CheckedItem) => {
      if (state !== 'CHECKED') {
        return false
      }

      if (!projectsSelectable) {
        return node.nodeType === 'bt'
      }

      const item = getItem(items, node)

      if (item == null || item.isDisabled === true) {
        return false
      }

      if (item.parentId == null || !propagateCheck) {
        return true
      }

      const parent = getItem(items, getProjectFilter(item.parentId))
      return (
        parent == null ||
        parent.isDisabled === true ||
        matchNode(checkedItems, getNodeFromItem(parent))?.state !== 'CHECKED'
      )
    })
    .map(({node}) => node)

function ProjectBuildTypeSelectForm({
  selected,
  onSelect = noop,
  checked = emptyArray,
  onCheck = noop,
  allItemSelectable = false,
  buildTypesSelectable = true,
  projectsSelectable = allItemSelectable,
  nothingSelectable,
  allItemName = `<All projects${buildTypesSelectable ? ' and build configurations' : ''}>`,
  expandAll = false,
  includedBuildTypes,
  excludedBuildTypes,
  includedProjects,
  includedRootProjects,
  disabledProjects,
  containerClassName,
  hint,
  hintAction,
  onHintAction = noop,
  multiselect = false,
  includeRoot,
  propagateCheck = true,
  hidePopup,
  withPipelines,
}: ProjectBuildTypeSelectFormProps) {
  const showHint = hint != null && includedBuildTypes != null
  const isNodeSelectable = useCallback(
    (node: ProjectOrBuildTypeNode | null | undefined) => {
      if (node == null) {
        return nothingSelectable
      }
      switch (node.nodeType) {
        case 'all':
          return allItemSelectable
        case 'bt':
          return buildTypesSelectable
        case 'template':
          return buildTypesSelectable
        case 'project':
          return (
            projectsSelectable &&
            (includedProjects == null || includedProjects.includes(node.id!)) &&
            !disabledProjects?.includes(node.id!)
          )
        default:
          return false
      }
    },
    [
      allItemSelectable,
      buildTypesSelectable,
      disabledProjects,
      includedProjects,
      nothingSelectable,
      projectsSelectable,
    ],
  )
  const validatedSelected: ProjectOrBuildTypeNode | null | undefined = useMemo(
    () =>
      isNodeSelectable(selected)
        ? selected && cloneNode(selected)
        : allItemSelectable && !nothingSelectable
          ? {
              nodeType: 'all',
            }
          : null,
    [allItemSelectable, isNodeSelectable, nothingSelectable, selected],
  )

  if (validatedSelected != null) {
    validatedSelected.group = 'search'
  }

  const [{searchQuery, expandState}, {setSearchQuery, toggleExpandState}] = useProjectsSearch()

  const select = useCallback(
    (node: ProjectOrBuildTypeNode | null | undefined) => {
      if (multiselect) {
        return true
      }

      if (isNodeSelectable(node)) {
        onSelect(node)
        hidePopup()
        setSearchQuery('')
        return true
      }

      return false
    },
    [hidePopup, isNodeSelectable, multiselect, onSelect, setSearchQuery],
  )
  const treeFilter = useMemo(
    () => ({
      removeBuildTypes: !buildTypesSelectable,
      removeEmptyProjects: !projectsSelectable,
      includedBuildTypes,
      excludedBuildTypes,
      includedProjects,
      includedRootProjects,
      disabledProjects,
      includeRoot,
    }),
    [
      buildTypesSelectable,
      projectsSelectable,
      includedBuildTypes,
      excludedBuildTypes,
      includedProjects,
      includedRootProjects,
      disabledProjects,
      includeRoot,
    ],
  )
  const defaultTree = useDefaultSearchProjectsTree(null, treeFilter)
  const parentProjectIds = useAppSelector(
    state => getParentProjectIds(state, selected),
    shallowEqual,
  )
  const getExpandState = useCallback(
    (tree: WritableMap<FederationServerId, ProjectsTreeType | null | undefined>) => ({
      ...(expandAll
        ? getExpandAll(tree)
        : Object.fromEntries(
            parentProjectIds.map(id => [
              id,
              {
                id,
                expandState: 'EXPANDED',
              },
            ]),
          )),
      ...expandState,
    }),
    [expandAll, expandState, parentProjectIds],
  )
  const getDefaultSearchItems = useCallback(
    (query: string) =>
      createSelector(
        (state: State) => state.togglingOverview,
        getOverviewData,
        getOverviewProjectsHash,
        (togglingOverview, overviewData, overviewProjectsHash) =>
          createSearchProjectsTree({
            searchQuery: query,
            defaultTreeByServer: defaultTree,
            togglingOverview,
            overviewData,
            overviewProjectsHash,
            federationServers: [],
            includeRoot,
          }),
      ),
    [defaultTree, includeRoot],
  )
  const makeGetItems = useCallback(
    (query = '', getProjectsExpandState = getExpandAll) =>
      createSelector(
        getDefaultSearchItems(query),
        defaultSearchItems =>
          upgradeSearchProjectsTreeByExpandState(
            [],
            defaultSearchItems,
            getProjectsExpandState(defaultSearchItems),
            !!query,
          ).get(currentServerId) ?? emptyTree,
      ),
    [getDefaultSearchItems],
  )
  const getItems: (arg0: State) => ProjectsTreeType = useMemo(
    () => makeGetItems(searchQuery, getExpandState),
    [getExpandState, makeGetItems, searchQuery],
  )
  const items: Array<ProjectsTreeItem> = useAppSelector(state => getItems(state).data)
  const getUnfilteredItems = useMemo(
    () =>
      createSelector(
        makeGetItems(),
        ({hash}: ProjectsTreeType): KeyValue<SidebarItemId, ProjectsTreeItem> =>
          hash != null ? Object.fromEntries(hash.entries()) : getEmptyHash(),
      ),
    [makeGetItems],
  )
  const unfilteredItems = useAppSelector(getUnfilteredItems)
  const checkedItems: CheckedItems = useMemo(
    () => (checked.length > 0 ? normalizeChecks(unfilteredItems, checked, propagateCheck) : {}),
    [checked, propagateCheck, unfilteredItems],
  )
  const selectedItems = getSelectedItems(
    projectsSelectable,
    unfilteredItems,
    checkedItems,
    propagateCheck,
  )
  const selectedBuildTypesCount = selectedItems.filter(node => node.nodeType === 'bt').length
  const selectedProjectsCount = selectedItems.filter(node => node.nodeType === 'project').length
  const selectedText =
    [
      selectedProjectsCount > 0
        ? `${selectedProjectsCount} ${plur('project', selectedProjectsCount)}`
        : '',
      selectedBuildTypesCount > 0
        ? `${selectedBuildTypesCount} ${plur('build configuration', selectedBuildTypesCount)}`
        : '',
    ]
      .filter(Boolean)
      .join(' and ') || 'None'

  const placeholder = `Select a ${[
    projectsSelectable && 'project',
    buildTypesSelectable && 'build configuration',
  ]
    .filter(Boolean)
    .join(' or ')}`
  const searchPlaceholder = `Search ${buildTypesSelectable ? 'projects and build configurations' : 'projects'}`

  const allItems: Array<ProjectsTreeItem> = useMemo(() => {
    const filteredItems = withPipelines ? items : items.filter(item => item.itemType !== 'pipeline')
    if (allItemSelectable && searchQuery.length === 0) {
      return [
        {
          serverId: currentServerId,
          itemType: 'action',
          id: toCustomSidebarItemId('all item'),
          action: () => () =>
            select({
              nodeType: 'all',
            }),
          name: allItemName,
          level: 0,
          group: 'search',
          focusable: true,
        },
        ...filteredItems,
      ]
    }
    if (nothingSelectable && searchQuery.length === 0) {
      return [
        {
          serverId: currentServerId,
          itemType: 'action',
          id: toCustomSidebarItemId('nothing'),
          action: () => () => select(null),
          name: placeholder,
          level: 0,
          group: 'search',
          focusable: true,
        },
        ...filteredItems,
      ]
    }

    return filteredItems
  }, [
    allItemName,
    allItemSelectable,
    items,
    nothingSelectable,
    placeholder,
    searchQuery.length,
    select,
    withPipelines,
  ])

  const ready = useAppSelector(state => getProjectsAndOverviewReady(state))
  const dispatch = useAppDispatch()
  const onChangeSearchActive = useCallback(
    (active: boolean) => {
      if (!active && searchQuery.length > 0) {
        setSearchQuery('')
      }
    },
    [searchQuery.length, setSearchQuery],
  )

  const itemsWithLoading = useMemo(
    () => (ready ? allItems : [...allItems, null]),
    [allItems, ready],
  )
  const contextValue = useMemo(
    () => ({
      isPopup: true,
      isAdmin: false,
      isAction: true,
      isMultiselect: multiselect,
    }),
    [multiselect],
  )
  const formContent = useCallback(
    ({measureRef, contentRect}: MeasuredComponentProps) => (
      <div
        className={classNames(styles.container, containerClassName, {
          [styles.popupContainer]: !multiselect,
          [styles.multiselect]: multiselect,
        })}
        style={{
          height:
            SEARCH_HEIGHT +
            calculateRowOffset(itemsWithLoading.length, itemsWithLoading) +
            PADDING_BOTTOM +
            (showHint ? (contentRect.offset?.height ?? HINT_HEIGHT) : 0) +
            (allItems.length === 0 && ready ? PLACEHOLDER_HEIGHT : 0),
        }}
      >
        <ProjectsTree
          activeItem={validatedSelected}
          checkedItems={flattenCheckedItems(checkedItems).map(item => {
            const node = cloneNode(item.node)
            node.group = 'search'
            return {...item, node}
          })}
          className={styles.tree}
          contentClassName={styles.treeContent}
          dispatch={dispatch}
          isPopup
          ready={ready}
          items={allItems}
          placeholder={<span className={styles.placeholder}>{'Nothing found'}</span>}
          toggleExpandState={(projectId, expanded) =>
            toggleExpandState({
              projectId,
              expanded,
            })
          }
          toggleExpandAll={noop}
          searchActive
          searchQuery={searchQuery}
          renderSearch={({sidebarRef, collapsed, ...searchProps}) => (
            <ProjectTreeSearch
              {...searchProps}
              borderless
              wrapperClassName={styles.searchWrapper}
              searchQuery={searchQuery}
              onChangeQuery={setSearchQuery}
              onChangeActive={onChangeSearchActive}
              autoFocus
              onEscape={hidePopup}
              height={ControlsHeight.L}
              placeholder={searchPlaceholder}
              aria-label={searchPlaceholder}
            />
          )}
          onSelect={item => {
            if (item.itemType === 'action' && typeof item.action === 'function') {
              item.action()
              return
            }
            const hasSelected = select(getNodeFromItem(item))

            if (!hasSelected && item.itemType === 'project') {
              toggleExpandState({
                projectId: item.id,
                expanded: !item.expanded,
              })
            }
          }}
          onCheck={(item, isChecked) => {
            const hasChanged = isChecked
              ? checkItem(
                  unfilteredItems,
                  checkedItems,
                  item,
                  'CHECKED',
                  propagateCheck ? undefined : 'NOPROPAGATE',
                )
              : uncheckItem(
                  unfilteredItems,
                  checkedItems,
                  item,
                  propagateCheck ? undefined : 'NOPROPAGATE',
                )

            if (hasChanged) {
              onCheck(
                getSelectedItems(projectsSelectable, unfilteredItems, checkedItems, propagateCheck),
              )
            }
          }}
          projectsSelectable={projectsSelectable}
        >
          {showHint && (
            <div ref={measureRef} className={styles.hint}>
              {hint}
              {hintAction != null && (
                <Button className={styles.hintAction} onClick={onHintAction} inline>
                  {hintAction}
                </Button>
              )}
            </div>
          )}
        </ProjectsTree>
      </div>
    ),
    [
      allItems,
      onChangeSearchActive,
      checkedItems,
      containerClassName,
      dispatch,
      hidePopup,
      hint,
      hintAction,
      itemsWithLoading,
      multiselect,
      onCheck,
      onHintAction,
      projectsSelectable,
      propagateCheck,
      ready,
      searchPlaceholder,
      searchQuery,
      select,
      setSearchQuery,
      showHint,
      toggleExpandState,
      unfilteredItems,
      validatedSelected,
    ],
  )
  const form = useMemo(
    () => (
      <ProjectsTreeContext.Provider value={contextValue}>
        <Measure offset>{formContent}</Measure>
      </ProjectsTreeContext.Provider>
    ),
    [contextValue, formContent],
  )
  return (
    <>
      {form}
      {multiselect && <div className={styles.selectedNote}>{`${selectedText} selected`}</div>}
    </>
  )
}

export default memo(ProjectBuildTypeSelectForm)
