import type {State} from '../../../reducers/types'
import {getBuildType, getProject} from '../../../selectors'
import type {ProjectId, ProjectOrBuildTypeNode} from '../../../types'

const getProjectPath = (
  state: State,
  projectId: ProjectId | null | undefined,
): ReadonlyArray<ProjectId> =>
  projectId != null
    ? getProjectPath(state, getProject(state, projectId)?.parentProjectId).concat(projectId)
    : []

function getParentProjectId(
  state: State,
  node: ProjectOrBuildTypeNode | null | undefined,
): ProjectId | null | undefined {
  if (node == null) {
    return null
  }

  switch (node.nodeType) {
    case 'project':
      return getProject(state, node.id)?.parentProjectId

    case 'bt':
      return getBuildType(state, node.id)?.projectId

    default:
      return null
  }
}

export const getParentProjectIds = (
  state: State,
  node: ProjectOrBuildTypeNode | null | undefined,
): ReadonlyArray<ProjectId> => getProjectPath(state, getParentProjectId(state, node))
