import Button from '@jetbrains/ring-ui-built/components/button/button'
import Anchor from '@jetbrains/ring-ui-built/components/dropdown/anchor'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import {useCallback, useEffect, useMemo, useState} from 'react'

import {useSlice} from '../../../hooks/useSlice'
import {getProjectsArg, overviewArg} from '../../../rest/projects'
import {getFullPath, getProject} from '../../../selectors'
import {restApi} from '../../../services/rest'
import type {BuildTypeId, ProjectId, ProjectOrBuildTypeNode} from '../../../types'
import {cloneNode, ROOT_PROJECT_ID} from '../../../types'
import {emptyArray, noop} from '../../../utils/empty'
import Icon from '../Icon/Icon'
import MiddleEllipsis from '../MiddleEllipsis/MiddleEllipsis'
import Popup from '../Popup/Popup.lazy'
import OverviewStatusIcon from '../ProjectOrBuildTypeIcon/OverviewStatusIcon.container'
import {EntityIconType} from '../ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'

import ProjectBuildTypeSelectForm from './ProjectBuildTypeSelectForm'

import styles from './ProjectBuildTypeSelect.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

export type ProjectBuildTypeSelectProps = {
  allItemName?: string
  allItemSelectable?: boolean
  buildTypesSelectable?: boolean
  projectsSelectable?: boolean
  nothingSelectable?: boolean
  expandAll?: boolean
  excludedBuildTypes?: ReadonlyArray<BuildTypeId> | null | undefined
  includedBuildTypes?: ReadonlyArray<BuildTypeId> | null | undefined
  includedProjects?: ReadonlyArray<ProjectId> | null | undefined
  includedRootProjects?: ReadonlyArray<ProjectId> | null | undefined
  disabledProjects?: ReadonlyArray<ProjectId> | null | undefined
  includeRoot?: boolean
  className?: string
  popupClassName?: string
  containerClassName?: string
  textClassName?: string
  hint?: string | null | undefined
  hintAction?: string | null | undefined
  onHintAction?: () => unknown
  selected?: ProjectOrBuildTypeNode | null
  checked?: ReadonlyArray<ProjectOrBuildTypeNode>
  onSelect?: (arg0: ProjectOrBuildTypeNode | null | undefined) => unknown
  onCheck?: (arg0: ReadonlyArray<ProjectOrBuildTypeNode>) => unknown
  multiselect?: boolean
  buttonMode?: boolean
  forceFetch?: boolean
  directions?: Directions[]
  propagateCheck?: boolean
  withPipelines?: boolean
}

const defaultDirections = [Directions.BOTTOM_RIGHT]

export function ProjectBuildTypeSelect({
  selected,
  onSelect = noop,
  checked = emptyArray,
  onCheck = noop,
  allItemSelectable = false,
  buildTypesSelectable = true,
  projectsSelectable = allItemSelectable,
  nothingSelectable,
  allItemName = `<All projects${buildTypesSelectable ? ' and build configurations' : ''}>`,
  expandAll = false,
  includedBuildTypes,
  excludedBuildTypes,
  includedProjects,
  includedRootProjects,
  disabledProjects,
  className,
  popupClassName,
  containerClassName,
  textClassName,
  hint,
  hintAction,
  onHintAction = noop,
  multiselect = false,
  buttonMode = false,
  forceFetch = true,
  includeRoot,
  directions = defaultDirections,
  propagateCheck = true,
  withPipelines,
}: ProjectBuildTypeSelectProps) {
  const isNodeSelectable = useCallback(
    (node: ProjectOrBuildTypeNode | null | undefined) => {
      if (node == null) {
        return nothingSelectable
      }
      switch (node.nodeType) {
        case 'all':
          return allItemSelectable
        case 'bt':
          return buildTypesSelectable
        case 'template':
          return buildTypesSelectable
        case 'project':
          return (
            projectsSelectable &&
            (includedProjects == null || includedProjects.includes(node.id!)) &&
            !disabledProjects?.includes(node.id!)
          )
        default:
          return false
      }
    },
    [
      allItemSelectable,
      buildTypesSelectable,
      disabledProjects,
      includedProjects,
      nothingSelectable,
      projectsSelectable,
    ],
  )
  const validatedSelected: ProjectOrBuildTypeNode | null | undefined = useMemo(
    () =>
      isNodeSelectable(selected)
        ? selected && cloneNode(selected)
        : allItemSelectable && !nothingSelectable
          ? {
              nodeType: 'all',
            }
          : null,
    [allItemSelectable, isNodeSelectable, nothingSelectable, selected],
  )

  if (validatedSelected != null) {
    validatedSelected.group = 'search'
  }

  const [popupIsShown, {togglePopup, hidePopup}]: [
    boolean,
    {
      togglePopup(): void
      hidePopup(): void
    },
  ] = useSlice<
    boolean,
    {
      togglePopup: void
      hidePopup: void
    }
  >(
    {
      togglePopup: state => !state,
      hidePopup: () => false,
    },
    false,
  )

  const placeholder = `Select a ${[
    projectsSelectable && 'project',
    buildTypesSelectable && 'build configuration',
  ]
    .filter(Boolean)
    .join(' or ')}`

  const [fetchOverview] = restApi.endpoints.getAllProjectsNormalized.useLazyQuerySubscription()
  useEffect(() => {
    fetchOverview(overviewArg, !forceFetch)
  }, [fetchOverview, forceFetch, includeRoot])
  restApi.endpoints.getAllProjectsNormalized.useQuerySubscription(
    getProjectsArg(ROOT_PROJECT_ID, {
      withBuildTypes: true,
      withDescription: true,
      withAncestorProjects: true,
      withOnlyArchivedAncestorProjects: true,
      includeRoot,
      projectReceiveMeta: {
        sidebarProjectsLoaded: true,
      },
      withPipelines,
    }),
  )

  const name = useAppSelector(state => {
    switch (validatedSelected?.nodeType) {
      case 'project':
        return validatedSelected.id === ROOT_PROJECT_ID
          ? getProject(state, validatedSelected.id)?.name
          : getFullPath(state, validatedSelected)
              .map(item => item.name)
              .join(' / ')

      case 'bt':
        return getFullPath(state, validatedSelected)
          .map(item => item.name)
          .join(' / ')

      case 'all':
        return allItemName

      default:
        return null
    }
  })
  const anchorIcon = useMemo(() => {
    switch (validatedSelected?.nodeType) {
      case 'project':
        return (
          <OverviewStatusIcon
            className={styles.icon}
            type={EntityIconType.PROJECT}
            id={validatedSelected.id}
            ignoreStatus
          />
        )

      case 'bt':
        return (
          <OverviewStatusIcon
            className={styles.icon}
            type={EntityIconType.BUILD_TYPE}
            id={validatedSelected.id}
            ignoreStatus
          />
        )

      default:
        return null
    }
  }, [validatedSelected])

  const anchor = useMemo(() => {
    const AnchorComponent = buttonMode ? Button : Anchor
    const anchorProps = buttonMode
      ? {
          className: classNames(styles.anchorButton, {[styles.anchorButtonOpen]: popupIsShown}),
        }
      : {className: classNames(styles.anchorText, textClassName)}
    return (
      <AnchorComponent
        {...anchorProps}
        data-test-project-select-anchor
        active={popupIsShown}
        onClick={togglePopup}
        role="combobox"
        aria-expanded={popupIsShown}
        aria-label={name ?? placeholder}
      >
        {anchorIcon}
        <MiddleEllipsis className={styles.name}>{name ?? placeholder}</MiddleEllipsis>
        {buttonMode && (
          <div className={styles.arrow}>
            <Icon className={styles.arrowIcon} name="chevron-down" />
          </div>
        )}
      </AnchorComponent>
    )
  }, [buttonMode, popupIsShown, textClassName, togglePopup, anchorIcon, name, placeholder])

  const form = useMemo(
    () => (
      <ProjectBuildTypeSelectForm
        selected={selected}
        onSelect={onSelect}
        checked={checked}
        onCheck={onCheck}
        allItemSelectable={allItemSelectable}
        buildTypesSelectable={buildTypesSelectable}
        projectsSelectable={projectsSelectable}
        nothingSelectable={nothingSelectable}
        allItemName={allItemName}
        expandAll={expandAll}
        includedBuildTypes={includedBuildTypes}
        excludedBuildTypes={excludedBuildTypes}
        includedProjects={includedProjects}
        includedRootProjects={includedRootProjects}
        disabledProjects={disabledProjects}
        containerClassName={containerClassName}
        hint={hint}
        hintAction={hintAction}
        onHintAction={onHintAction}
        multiselect={multiselect}
        forceFetch={forceFetch}
        includeRoot={includeRoot}
        propagateCheck={propagateCheck}
        hidePopup={hidePopup}
        withPipelines={withPipelines}
      />
    ),
    [
      allItemName,
      allItemSelectable,
      buildTypesSelectable,
      checked,
      containerClassName,
      disabledProjects,
      excludedBuildTypes,
      expandAll,
      forceFetch,
      hidePopup,
      hint,
      hintAction,
      includeRoot,
      includedBuildTypes,
      includedProjects,
      includedRootProjects,
      multiselect,
      nothingSelectable,
      onCheck,
      onHintAction,
      onSelect,
      projectsSelectable,
      propagateCheck,
      selected,
      withPipelines,
    ],
  )

  return multiselect ? (
    form
  ) : (
    <div className={className}>
      {anchor}
      <Popup
        className={classNames(popupClassName, styles.popup)}
        hidden={!popupIsShown}
        directions={directions}
        onCloseAttempt={hidePopup}
        dontCloseOnAnchorClick
        top={8}
      >
        {form}
      </Popup>
    </div>
  )
}
export default function StatefulProjectBuildTypeSelect({
  selected: initialSelected,
  checked: initialChecked,
  onSelect = noop,
  onCheck = noop,
  ...restProps
}: ProjectBuildTypeSelectProps) {
  const [selected, setSelected] = useState(initialSelected)
  const [checked, setChecked] = useState(initialChecked)
  return (
    <ProjectBuildTypeSelect
      {...restProps}
      selected={selected}
      checked={checked}
      onSelect={item => {
        setSelected(item)
        onSelect(item)
      }}
      onCheck={items => {
        setChecked(items)
        onCheck(items)
      }}
    />
  )
}
